/**
 * SIGN (Scottish Intercollegiate Guidelines Network) search filters.
 *
 * Canonical source: https://www.sign.ac.uk/using-our-guidelines/methodology/search-filters/
 * Verbatim Ovid Medline / Embase / CINAHL syntax extracted from the official Word templates.
 * Do not edit operator syntax by hand — re-extract from SIGN templates if they update.
 */

export type SignFilterId =
  | "diagnostic-studies"
  | "economic-studies"
  | "observational-studies"
  | "patient-issues"
  | "randomised-controlled-trials"
  | "systematic-reviews";

export type SignDatabaseSection = "medline" | "embase" | "cinahl";

export interface SignFilterLine {
  /** Ovid line number when present; null for EBSCO S-lines or merged continuations. */
  lineNumber: number | null;
  query: string;
}

export interface SignFilter {
  id: SignFilterId;
  title: string;
  attribution: string;
  pageUrl: string;
  templateUrl: string;
  sections: Partial<Record<SignDatabaseSection, SignFilterLine[]>>;
}

