export function getSignFilter(id: SignFilterId): SignFilter {
  return SIGN_FILTERS[id];
}

/** Final Ovid combine line for filters that end with a numbered boolean (e.g. RCT "24 not 28"). */
export function getSignFilterFinalLine(
  id: SignFilterId,
  database: SignDatabaseSection,
): string | undefined {
  const section = SIGN_FILTERS[id].sections[database];
  if (!section?.length) return undefined;
  const last = section[section.length - 1];
  if (last.lineNumber == null) return last.query;
  if (/^(or\/|\d+\s+(or|not|and)\b)/i.test(last.query)) return last.query;
  return undefined;
}
